    // small bump on the groove floor near the locked end of each slot;
    // lug (0.4 above floor) rides over the 0.7 bump (0.3 press) then settles past it
    for (i = [0 : lug_count - 1]) {
        a = i * 360 / lug_count;
        rotate([0, 0, a + 80])
            rotate_extrude(angle = 4)
                polygon(points = [[slot_bot_r - 0.1, slot_z_bot], [34.0, slot_z_bot],
